    packageData.oneD=Array.from({length:packageData.frameCount},()=>Array.from({length:packageData.provenance.paths_1d},()=>readValues(packageData.nLine)));
    packageData.twoD=Array.from({length:packageData.frameCount},()=>readValues(packageData.nx*packageData.ny));
